import sys

def solve():
    N, K, L = map(int, input().split())
    roads = [tuple(map(int, input().split())) for _ in range(K)]
    railways = [tuple(map(int, input().split())) for _ in range(L)]

    # Create a graph for roads and railways
    road_graph = [[] for _ in range(N)]
    railway_graph = [[] for _ in range(N)]

    for i in range(K):
        road_graph[roads[i][0] - 1].append(roads[i][1] - 1)
        road_graph[roads[i][1] - 1].append(roads[i][0] - 1)

    for i in range(L):
        railway_graph[railways[i][0] - 1].append(railways[i][1] - 1)
        railway_graph[railways[i][1] - 1].append(railways[i][0] - 1)

    # Count the number of cities connected by both roads and railways for each city
    result = [0] * N
    for i in range(N):
        for j in range(N):
            if i != j:
                if i in road_graph[j] and j in railway_graph[i]:
                    result[i] += 1

    # Print the result
    for i in range(N):
        print(result[i])

if __name__ == "__main__":
    solve()
```

