import sys

def min_strokes(x1, y1, x2, y2, H, W, K, c):
    if x1 == x2 and y1 == y2:
        return 0
    if x1 > x2 or y1 > y2:
        return -1
    if c[x1][y1] == '@':
        return -1
    if c[x2][y2] == '@':
        return -1
    if x1 == x2 and y1 == y2:
        return 0
    if x1 == x2:
        return min(K, W - y1 + 1)
    if y1 == y2:
        return min(K, H - x1 + 1)
    if c[x1][y1] == '@' or c[x2][y2] == '@':
        return -1
    if c[x1][y1] == '.' and c[x2][y2] == '.':
        return min(K, min(W - y1 + 1, H - x1 + 1))
    if c[x1][y1] == '.':
        return min(K, W - y1 + 1) + min_strokes(x1, y1 + 1, x2, y2, H, W, K, c)
    if c[x2][y2] == '.':
        return min(K, H - x1 + 1) + min_strokes(x1, y1, x2, y2, H, W, K, c)

H, W, K = map(int, input().split())
